function addCalendarFilters(ctx){const toolbar=document.querySelector('.calendar-pro-toolbar');if(!toolbar||document.querySelector('.calendar-filterbar'))return;const bar=document.createElement('section');bar.className='calendar-filterbar';bar.innerHTML=`<select id="calendarFilterFormation">${filterOptions(ctx.contacts.map(c=>c.formation),'','Toutes les formations',ctx.esc)}</select><select id="calendarFilterOrigin">${filterOptions(ctx.contacts.flatMap(sourceLabels),'','Toutes les origines',ctx.esc)}</select><select id="calendarFilterHost">${filterOptions(ctx.appointments().map(item=>item.host_name),'','Tous les commerciaux',ctx.esc)}</select><select id="calendarFilterType">${filterOptions(ctx.appointments().map(item=>item.name||item.event_type_name),'','Tous les types de RDV',ctx.esc)}</select>`;toolbar.insertAdjacentElement('afterend',bar);const apply=()=>{document.querySelectorAll('.calendar-pro-event').forEach(card=>{const id=card.querySelector('[data-appointment-response]')?.dataset.appointmentResponse,appointment=ctx.appointments().find(item=>String(item.id)===String(id)),contact=ctx.contacts.find(item=>String(item.id)===String(appointment?.contact_id))||appointment?.contact||{},show=(!calendarFilterFormation.value||contact.formation===calendarFilterFormation.value)&&(!calendarFilterOrigin.value||sourceLabels(contact).includes(calendarFilterOrigin.value))&&(!calendarFilterHost.value||appointment?.host_name===calendarFilterHost.value)&&(!calendarFilterType.value||(appointment?.name||appointment?.event_type_name)===calendarFilterType.value);card.hidden=!show})};bar.querySelectorAll('select').forEach(select=>select.oninput=apply)}
