function directionComparison(ctx){if(state.directionPeriod==='all')return;const now=new Date(),currentStart=state.directionPeriod==='month'?new Date(now.getFullYear(),now.getMonth(),1):new Date(now.getFullYear(),0,1),previousStart=state.directionPeriod==='month'?new Date(now.getFullYear(),now.getMonth()-1,1):new Date(now.getFullYear()-1,0,1),previousEnd=state.directionPeriod==='month'?new Date(now.getFullYear(),now.getMonth(),1):new Date(now.getFullYear(),0,1),lastYearStart=new Date(currentStart),lastYearEnd=new Date(now);lastYearStart.setFullYear(lastYearStart.getFullYear()-1);lastYearEnd.setFullYear(lastYearEnd.getFullYear()-1);const sum=(start,end)=>ctx.contacts.filter(contact=>contact.statut==='Converti'&&dateValue(contact.converted_at||contact.updated_at||contact.created_at)>=start&&dateValue(contact.converted_at||contact.updated_at||contact.created_at)<end).reduce((total,contact)=>total+Number(contact.prix_vente||0),0),current=sum(currentStart,new Date(now.getTime()+1)),previous=sum(previousStart,previousEnd),lastYear=sum(lastYearStart,lastYearEnd),delta=reference=>reference?Math.round((current-reference)/reference*100):current?100:0;document.querySelector('.direction-toolbar')?.insertAdjacentHTML('afterend',`<section class="direction-comparison"><div><span>Période affichée</span><b>${money(current)}</b></div><div><span>Vs période précédente</span><b class="${delta(previous)>=0?'positive':'negative'}">${delta(previous)>=0?'↑':'↓'} ${Math.abs(delta(previous))} %</b><small>${money(previous)}</small></div><div><span>Vs année précédente</span><b class="${delta(lastYear)>=0?'positive':'negative'}">${delta(lastYear)>=0?'↑':'↓'} ${Math.abs(delta(lastYear))} %</b><small>${money(lastYear)}</small></div></section>`)}
